import { availableCopies } from "./store.mjs";

const byTitle = (a, b) => {
  const x = a.title.toLowerCase();
  const y = b.title.toLowerCase();
  return x < y ? -1 : x > y ? 1 : 0;
};

export function search(store, query = {}) {
  const { q, author, tag, yearFrom, yearTo, available, sort = "title" } = query;
  const page = query.page ?? 1;
  const pageSize = query.pageSize ?? 10;
  const words = (q ?? "").toLowerCase().split(/\s+/).filter(Boolean);
  const wantAuthor = author?.toLowerCase();

  const matches = store.books.filter((b) => {
    const hay = `${b.title} ${b.author}`.toLowerCase();
    if (!words.every((w) => hay.includes(w))) return false;
    if (wantAuthor !== undefined && b.author.toLowerCase() !== wantAuthor) return false;
    if (tag !== undefined && !b.tags.includes(tag)) return false;
    if (yearFrom !== undefined && b.year < yearFrom) return false;
    if (yearTo !== undefined && b.year > yearTo) return false;
    if (available === true && availableCopies(store, b.id) <= 0) return false;
    return true;
  });

  matches.sort(sort === "year" ? (a, b) => b.year - a.year || byTitle(a, b) : byTitle);
  const total = matches.length;
  const start = (page - 1) * pageSize;
  return { items: matches.slice(start, start + pageSize), total, page, pages: Math.ceil(total / pageSize) };
}
