import { createServer as httpServer } from "node:http";
import { search } from "./search.mjs";
import { getBook, checkout } from "./store.mjs";
import { memberBalance } from "./fines.mjs";

function send(res, status, body) {
  res.writeHead(status, { "Content-Type": "application/json" });
  res.end(JSON.stringify(body));
}

const notFound = (res) => send(res, 404, { error: "not found" });

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (c) => (data += c));
    req.on("end", () => resolve(data));
    req.on("error", reject);
  });
}

export function createServer(store) {
  return httpServer(async (req, res) => {
    try {
      const url = new URL(req.url, "http://localhost");
      const parts = url.pathname.split("/").filter(Boolean).map(decodeURIComponent);
      const p = url.searchParams;

      if (req.method === "GET" && parts.length === 1 && parts[0] === "books") {
        const query = {};
        for (const k of ["q", "author", "tag"]) if (p.has(k)) query[k] = p.get(k);
        for (const k of ["page", "pageSize"]) if (p.has(k)) query[k] = Number(p.get(k));
        return send(res, 200, search(store, query));
      }
      if (req.method === "GET" && parts.length === 2 && parts[0] === "books") {
        const book = getBook(store, parts[1]);
        return book ? send(res, 200, book) : notFound(res);
      }
      if (req.method === "POST" && parts.length === 1 && parts[0] === "loans") {
        let body;
        try {
          body = JSON.parse(await readBody(req));
        } catch {
          return send(res, 400, { error: "invalid json" });
        }
        if (body === null || typeof body !== "object") return send(res, 400, { error: "invalid json" });
        for (const f of ["bookId", "memberId", "date"]) {
          if (body[f] === undefined || body[f] === null || body[f] === "") return send(res, 400, { error: `missing ${f}` });
        }
        try {
          return send(res, 201, checkout(store, body.bookId, body.memberId, body.date));
        } catch (e) {
          return send(res, 409, { error: e.message });
        }
      }
      if (req.method === "GET" && parts.length === 3 && parts[0] === "members" && parts[2] === "balance") {
        return send(res, 200, { memberId: parts[1], balance: memberBalance(store, parts[1], p.get("asOf")) });
      }
      return notFound(res);
    } catch (e) {
      send(res, 500, { error: e.message });
    }
  });
}
