// CSV export/import of books.
import { addBook } from "./store.mjs";

const COLUMNS = ["title", "author", "year", "tags", "copies"];

const quote = (v) => {
  const s = String(v);
  return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};

export function exportBooks(store) {
  const lines = ["id,title,author,year,tags,copies"];
  for (const b of store.books) {
    lines.push([b.id, b.title, b.author, b.year, b.tags.join(";"), b.copies].map(quote).join(","));
  }
  return lines.join("\n") + "\n";
}

// Returns [{ line, fields }] where line is the 1-based line the row starts on.
function parseRows(text) {
  const rows = [];
  let fields = [];
  let field = "";
  let inQuotes = false;
  let line = 1;
  let rowLine = 1;
  let pending = false;
  const endRow = () => {
    fields.push(field);
    rows.push({ line: rowLine, fields });
    fields = [];
    field = "";
    pending = false;
  };
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; } else inQuotes = false;
      } else {
        if (c === "\n") line++;
        field += c;
      }
    } else if (c === '"') {
      inQuotes = true;
      pending = true;
    } else if (c === ",") {
      fields.push(field);
      field = "";
      pending = true;
    } else if (c === "\n" || c === "\r") {
      if (c === "\r" && text[i + 1] === "\n") i++;
      endRow();
      line++;
      rowLine = line;
    } else {
      field += c;
      pending = true;
    }
  }
  if (pending || field !== "") endRow();
  return rows;
}

export function importBooks(store, text) {
  const rows = parseRows(text);
  const result = { added: 0, errors: [] };
  if (rows.length === 0) throw new Error("missing header");
  const header = rows[0].fields.map((h) => h.trim());
  for (const col of COLUMNS) {
    if (!header.includes(col)) throw new Error(`missing column: ${col}`);
  }
  const idx = Object.fromEntries(COLUMNS.map((c) => [c, header.indexOf(c)]));
  for (const { line, fields } of rows.slice(1)) {
    if (fields.length === 1 && fields[0].trim() === "") continue; // blank line
    const get = (c) => (fields[idx[c]] ?? "").trim();
    const title = get("title");
    const author = get("author");
    const year = get("year");
    const copies = get("copies");
    let message = null;
    if (!title) message = "title is required";
    else if (!author) message = "author is required";
    else if (!/^-?\d+$/.test(year)) message = "year must be a whole number";
    else if (copies !== "" && !(/^\d+$/.test(copies) && Number(copies) > 0)) message = "copies must be a positive whole number";
    if (message) {
      result.errors.push({ line, message });
      continue;
    }
    const tagText = get("tags");
    addBook(store, {
      title,
      author,
      year: Number(year),
      tags: tagText === "" ? [] : tagText.split(";"),
      copies: copies === "" ? 1 : Number(copies),
    });
    result.added++;
  }
  return result;
}
